package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class SpecialtyRulesTest {
 Map<String,Object> dic(){return new HashMap<>(Map.of("adult",true,"underlying",true,"platelets",40d,"ptProlongation",6d,"dDimerFold",8d,"fibrinogen",.8));}
 @Test void emptyInputsNeverBecomeNegative(){for(String key:SpecialtyRules.FIELDS.keySet())assertEquals("unknown",SpecialtyRules.evaluate(key,Map.of()).get("status"));assertEquals(5,SpecialtyRules.schema().size());}
 @Test void dicUses2025FoldBoundariesAndDoesNotSubstituteInr(){var v=dic();assertEquals(8,SpecialtyRules.evaluate("dic",v).get("score"));v.put("dDimerFold",7d);assertEquals(7,SpecialtyRules.evaluate("dic",v).get("score"));v.remove("ptProlongation");v.put("inr",2d);assertEquals("unknown",SpecialtyRules.evaluate("dic",v).get("status"));}
 @Test void nonFiniteNegativeAndZeroPfDoNotCount(){var v=dic();v.put("platelets",Double.NaN);assertEquals("unknown",SpecialtyRules.evaluate("dic",v).get("status"));v.put("platelets",-1);assertEquals("unknown",SpecialtyRules.evaluate("dic",v).get("status"));}
 @Test void ardsRequiresImagingAndCardiacCauseReviewButNotIrrelevantHfnoFlow(){var v=new HashMap<String,Object>(Map.of("adult",true,"acuteWeek",true,"bilateral",true,"nonCardiac",true,"support","invasive","peep",5,"pf",100,"measurementValid",true));var r=SpecialtyRules.evaluate("ards",v);assertEquals("candidate",r.get("status"));assertEquals("重度参考",r.get("stage"));v.remove("bilateral");assertEquals("unknown",SpecialtyRules.evaluate("ards",v).get("status"));v.put("bilateral",true);v.put("pf",0);assertEquals("unknown",SpecialtyRules.evaluate("ards",v).get("status"));}
 @Test void hfnoBranchRequiresFlowInsteadOfPeep(){var v=Map.<String,Object>of("adult",true,"acuteWeek",true,"bilateral",true,"nonCardiac",true,"support","hfno","flow",30,"pf",200,"measurementValid",true);assertEquals("candidate",SpecialtyRules.evaluate("ards",v).get("status"));assertNull(SpecialtyRules.evaluate("ards",v).get("stage"));}
 @Test void camCannotBeNegativeInDeepSedationOrInferredFromGcs(){var v=new HashMap<String,Object>(Map.of("adult",true,"rass",-4,"camPerformed",true,"feature1",true,"feature2",true,"feature3",true,"feature4",false));assertEquals("not_assessable",SpecialtyRules.evaluate("delirium",v).get("status"));v.put("rass",0);assertEquals("candidate",SpecialtyRules.evaluate("delirium",v).get("status"));v.remove("feature2");v.put("gcs",3);assertEquals("unknown",SpecialtyRules.evaluate("delirium",v).get("status"));}
 @Test void liverCannotBeDiagnosedFromInrAndGcsAlone(){assertEquals("unknown",SpecialtyRules.evaluate("liver",Map.of("adult",true,"inr",2,"gcs",3)).get("status"));assertEquals("candidate",SpecialtyRules.evaluate("liver",Map.of("adult",true,"acuteInjury",true,"inr",1.5,"hepaticEncephalopathy",true,"within26Weeks",true,"noCirrhosis",true)).get("status"));}
 @Test void akiRequiresConfirmedBaselineAndAcuteContextOrAbsoluteRise(){var v=new HashMap<String,Object>(Map.of("adult",true,"baseline",80,"baselineStable",false,"acute7d",true,"currentCreatinine",240,"chronicDialysis",false));assertEquals("unknown",SpecialtyRules.evaluate("aki",v).get("status"));v.put("baselineStable",true);assertEquals(3,SpecialtyRules.evaluate("aki",v).get("stage"));v.put("chronicDialysis",true);assertEquals("not_assessable",SpecialtyRules.evaluate("aki",v).get("status"));}
 @Test void sfPathRequiresSignalEligibilityAndStableMeasurement(){var v=new HashMap<String,Object>(Map.of("adult",true,"acuteWeek",true,"bilateral",true,"nonCardiac",true,"support","invasive","peep",5,"sf",148,"sfValid",true,"measurementValid",true));assertEquals("重度参考",SpecialtyRules.evaluate("ards",v).get("stage"));v.put("sfValid",false);assertEquals("unknown",SpecialtyRules.evaluate("ards",v).get("status"));}
}
